--刷新list数据 第一次选中默认是全选
function UIFishPoolCreelBatchNode:RefreshListData(allFishDatas, fishDojo, isSelect)  
    self._allFishDatas = allFishDatas

    --不是nil只选了一个
    if fishDojo then
        if not isSelect then
            local dojo = FishingUtils.GetFishingFishDojo(fishDojo.fishId, fishDojo.rating)
            self._selelctIdNumMap[checkString(dojo.fishId).."_"..checkString(dojo.rating)] = {
                fishId = dojo.fishId, 
                rating = dojo.rating, 
                num = checkNumber(dojo.num)
            } 
        else
            local dojo = FishingUtils.GetFishingFishDojo(fishDojo.fishId, fishDojo.rating)
            self._selelctIdNumMap[checkString(dojo.fishId).."_"..checkString(dojo.rating)] = nil
        end
    --全部的刷新
    else
        self._selelctIdNumMap = {}
        for k, v in pairs(self._allFishDatas) do
            self._selelctIdNumMap[checkString(v.fishId).."_"..checkString(v.rating)] = {
                fishId = v.fishId, 
                rating = v.rating, 
                num = checkNumber(v.num)
            } 
        end
    end

    self:FillSelf()
end

function UIFishPoolCreelBatchNode:FillSelf()
    local titleName = ""
    local path = ""
    if self._curType == ConstantsFishing.FishBasketType.Make then
        titleName = localize("批量制作")
        path = "UIAtlas/FishPool/fish_pool_img_fishfood.png"
        self.FontStyleButton:ResetFontStyle("B6", localize("制作"))
        SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnMark))
        KTool.SetActive(self.PriceTotalGroup, false)
    elseif self._curType == ConstantsFishing.FishBasketType.Sell then
        titleName = localize("批量出售")
        self.FontStyleButton:ResetFontStyle("B6", localize("出售"))
        path = GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.FishCurrency)
        SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnSell))
        KTool.SetActive(self.PriceTotalGroup, true)
    end
    CfUtils.FillText(self.TextTitle, titleName)
    CfUtils.FillImage(self.Image, path)

    self:RefreshListInfo()
    self:RefreshTotalNum()
end

