function UIFishPoolCreelBatchNode:RefreshTotalNum()
    local num = 0
    for k, data in pairs(self._selelctIdNumMap) do
        local vo = FishingUtils.GetFishingSpeciesVo(data.fishId)
        if vo then
            if self._curType == ConstantsFishing.FishBasketType.Make then
                num = num + checkNumber(vo.baitNum) * data.num
            elseif self._curType == ConstantsFishing.FishBasketType.Sell then
                local ratingVo = FishingUtils.GetFishingRatingVo(data.rating)
                if ratingVo then
                    num = num + (math.floor(vo.price * (1 + ratingVo.priceAddition)) * data.num)
                end
            end
        end
    end
    if self._curType == ConstantsFishing.FishBasketType.Sell then
        local path = GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.FishCurrency)
        CfUtils.FillImage(self.ImgIcon, path)
        CfUtils.FillText(self.TextNumber, num)
    end
end

function UIFishPoolCreelBatchNode:RefreshListInfo()
    if self._isInitList then
        GameUtils.ReloadData(self.LoopList, table.count(self._allFishDatas))
    else
        self.LoopList:InitListView(table.count(self._allFishDatas), Bind(self, self.OnRefreshIndex))
        self._isInitList = true
    end
end

function UIFishPoolCreelBatchNode:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local data = self._allFishDatas[index + 1]
    local scr = CfUtils.GetLuaScr(cell, UIFishPoolCreelBatchItemNode)
    if scr then
        scr:Refresh(data, self._curType, function(num)
            self._selelctIdNumMap[checkString(data.fishId).."_"..checkString(data.rating)] = {
                fishId = data.fishId, 
                rating = data.rating, 
                num = num
            } 
            self:RefreshTotalNum()
        end)
    end
    return cell
end

--取消
function UIFishPoolCreelBatchNode:OnBtnCancel()
    if not self._cancelCb then
        return
    end
    self._cancelCb()
end

